import { describe, expect, it } from "vitest";
import { deliveryReason } from "./index";

describe("deliveryReason", () => {
  it("shows the first error line a hook printed, not the git command", () => {
    const message = [
      "Command failed: git -C /tmp/w commit -m Tint headers -m Generated by YugoTool.",
      "┃  oxlint ❯",
      'packages/x.tsx:68:20: error shadcn(no-raw-colors): "bg-violet-50" uses the raw Tailwind palette.',
    ].join("\n");
    expect(deliveryReason(message)).toBe(
      'packages/x.tsx:68:20: error shadcn(no-raw-colors): "bg-violet-50" uses the raw Tailwind palette.',
    );
  });

  it("finds a commit-msg hook's ✖ line", () => {
    const message = [
      "Command failed: git -C /tmp/w commit -m Add a footer note -m Generated by YugoTool.",
      "✔ lint: 2 files clean",
      '✖ commit-msg: subject must follow Conventional Commits, e.g. "feat: add a footer note"',
    ].join("\n");
    expect(deliveryReason(message)).toMatch(/^✖ commit-msg: subject must follow/);
  });

  it("falls back to the first line", () => {
    expect(deliveryReason("gh: not logged in\nrun gh auth login")).toBe("gh: not logged in");
  });
});
